package ru.truetv.launcher;
import android.app.*;import android.content.*;import android.content.pm.*;import android.os.*;import android.service.notification.*;import android.view.*;import android.view.accessibility.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;
/** Real OS notification access, cross-UID posts/updates/removal, counter and foreground UI. */
public final class NoticesCheck extends Instrumentation {
 private Context c;private HomeActivity home;private NoticesActivity screen;private UiAutomation automation;private String beforeAccess;private boolean oldPost;private Map<String,?> beforeSettings;private int checks;private final StringBuilder log=new StringBuilder();
 public void onCreate(Bundle b){super.onCreate(b);start();}private void main(Runnable r){runOnMainSync(r);waitForIdleSync();}private void check(boolean ok,String text){checks++;log.append(ok?"PASS ":"FAIL ").append(text).append('\n');if(!ok)throw new AssertionError(text);}interface Wait{boolean ok()throws Exception;}private void until(Wait w)throws Exception{long end=SystemClock.uptimeMillis()+30000;while(!w.ok()&&SystemClock.uptimeMillis()<end){VmWindows.clear(this);Thread.sleep(100);}check(w.ok(),"await condition");}private Object f(Object o,String n)throws Exception{Field field=o.getClass().getDeclaredField(n);field.setAccessible(true);return field.get(o);}private String shell(String command)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(automation.executeShellCommand(command))){byte[] data=new byte[1024];int n;while((n=in.read(data))!=-1)out.write(data,0,n);}return out.toString("UTF-8").trim();}private void probe(String op)throws Exception{shell("am broadcast -n ru.truetv.probe/ru.truetv.probe.NoticeProbe --es op "+op);}private List<Notices.Entry> sample(){ArrayList<Notices.Entry> result=new ArrayList<>();for(Notices.Entry e:Notices.snapshot(c))if(e.pkg.equals("ru.truetv.probe"))result.add(e);return result;}private AccessibilityNodeInfo dialogButton(String text){AccessibilityNodeInfo root=automation.getRootInActiveWindow();if(root==null)return null;for(AccessibilityNodeInfo node:root.findAccessibilityNodeInfosByText(text))if("android.widget.Button".contentEquals(node.getClassName())&&text.contentEquals(node.getText()))return node;return null;}private void details(Notices.Entry target)throws Exception{until(()->((ArrayList<?>)f(screen,"entries")).size()==Notices.count(c));main(()->{try{ArrayList<?> entries=(ArrayList<?>)f(screen,"entries");int pos=-1;for(int n=0;n<entries.size();n++)if(((Notices.Entry)entries.get(n)).key.equals(target.key))pos=n;if(pos<0)throw new AssertionError("Missing notification row");((ListView)f(screen,"list")).performItemClick(null,pos,pos);}catch(Exception e){throw new RuntimeException(e);}});}private void shot(String name)throws Exception{waitForIdleSync();Thread.sleep(800);android.graphics.Bitmap b=automation.takeScreenshot();if(b==null){log.append("SCREENSHOT unavailable on this VM display\n");return;}try(OutputStream out=new FileOutputStream(new File(c.getExternalFilesDir(null),"notices243-"+name+"-api"+Build.VERSION.SDK_INT+".png"))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 public void onStart(){Bundle result=new Bundle();try{c=getTargetContext();check(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("Android SDK"),"VM guard");beforeSettings=new HashMap<>(new SettingsStore(c).data.getAll());new SettingsStore(c).data.edit().putBoolean("bt_count",false).putBoolean("bt_asked",true).commit();automation=getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES);android.accessibilityservice.AccessibilityServiceInfo info=automation.getServiceInfo();info.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;automation.setServiceInfo(info);beforeAccess=shell("settings get secure enabled_notification_listeners");if(Build.VERSION.SDK_INT>=33){oldPost=c.getPackageManager().checkPermission("android.permission.POST_NOTIFICATIONS","ru.truetv.probe")==PackageManager.PERMISSION_GRANTED;shell("pm grant ru.truetv.probe android.permission.POST_NOTIFICATIONS");}shell("cmd notification disallow_listener ru.truetv.launcher/ru.truetv.launcher.Notices");home=VmWindows.home(this);until(()->home.hasWindowFocus());check(home.header.getChildAt(7).getContentDescription().toString().contains("Notifications")||home.header.getChildAt(7).getContentDescription().toString().contains("Уведомления"),"notification control is directly before power");check(home.header.getChildAt(8).getNextFocusRightId()==home.header.getChildAt(0).getId(),"nine system controls keep cyclic remote focus");check(((ViewGroup)home.header.getParent()).getChildCount()==3,"no new help row or desktop rebuild reserve");check(Notices.count(c)==-1,"missing notification access is unknown rather than a fake zero");Board board=home.board;View tile=board.getChildAt(0);
 ActivityMonitor m=new ActivityMonitor(NoticesActivity.class.getName(),null,false);addMonitor(m);main(()->home.header.getChildAt(7).performClick());screen=(NoticesActivity)waitForMonitorWithTimeout(m,15000);removeMonitor(m);check(screen!=null,"top control opens the notifications screen");until(()->screen.hasWindowFocus());check(((View)f(screen,"permission")).getVisibility()==View.VISIBLE,"access is requested only through an explicit Android settings button");check(!Notices.granted(c),"opening the screen did not enable notification access automatically");main(screen::finish);screen=null;until(()->home.hasWindowFocus());shell("cmd notification allow_listener ru.truetv.launcher/ru.truetv.launcher.Notices");until(()->Notices.connected(c));probe("post");until(()->sample().size()==2);check(sample().stream().noneMatch(e->e.summary),"group summary is excluded when its child notifications are present");until(()->(Integer)f(f(home,"noticesBadge"),"count")==Notices.count(c));check(home.board==board&&board.getChildAt(0)==tile,"notification events reuse the existing desktop and tiles");shot("counter");probe("update");until(()->sample().stream().anyMatch(e->e.text.equals("Updated notification text")));check(sample().size()==2,"reposting the same notification updates content without duplicating it");
 m=new ActivityMonitor(NoticesActivity.class.getName(),null,false);addMonitor(m);main(()->home.header.getChildAt(7).performClick());screen=(NoticesActivity)waitForMonitorWithTimeout(m,15000);removeMonitor(m);until(()->screen.hasWindowFocus());ListView list=(ListView)f(screen,"list");check(list.getAdapter().getCount()==Notices.count(c),"screen list and header use the same live notification count");shot("list");Notices.Entry first=sample().stream().filter(e->e.id==2451).findFirst().get();details(first);String dismiss=Ui.word(c,"Убрать уведомление","Dismiss notification");until(()->dialogButton(dismiss)!=null);check(dialogButton(dismiss).performAction(AccessibilityNodeInfo.ACTION_CLICK),"actual detail Dismiss button accepts remote activation");until(()->sample().size()==1);check(sample().get(0).text.equals("Updated notification text"),"dismissal updates the live list without removing another notification");Notices.Entry last=sample().get(0);details(last);String open=Ui.word(c,"Открыть","Open");until(()->dialogButton(open)!=null);check(dialogButton(open).performAction(AccessibilityNodeInfo.ACTION_CLICK),"actual detail Open button accepts remote activation");until(()->{AccessibilityNodeInfo root=automation.getRootInActiveWindow();return root!=null&&"ru.truetv.probe".contentEquals(root.getPackageName())&&!root.findAccessibilityNodeInfosByText("Notification open243").isEmpty();});check(true,"original cross-app PendingIntent opens its real target");probe("clear");shell("input keyevent 4");if(screen!=null)main(screen::finish);screen=null;until(()->home.hasWindowFocus());until(()->sample().isEmpty());Board previousBoard=home.board;SettingsActivity settingsScreen=(SettingsActivity)startActivitySync(new Intent(c,SettingsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));until(()->settingsScreen.hasWindowFocus());main(()->{SettingsStore prefs=new SettingsStore(c);prefs.data.edit().putString("columns",prefs.columns()==5?"6":"5").commit();prefs.layoutChanged();settingsScreen.finish();});until(()->home.hasWindowFocus()&&home.board!=previousBoard);check((Integer)f(f(home,"noticesBadge"),"count")==Notices.count(c),"counter is immediately correct after returning from a grid settings rebuild");board=home.board;tile=board.getChildAt(0);shell("cmd notification disallow_listener ru.truetv.launcher/ru.truetv.launcher.Notices");until(()->!Notices.connected(c));check(Notices.snapshot(c).isEmpty()&&Notices.count(c)==-1,"revoking access clears content and stops reporting a count");check(home.board==board&&board.getChildAt(0)==tile,"grant/revoke and all notification changes preserve desktop instances");result.putBoolean("passed",true);
 }catch(Throwable e){StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));log.append(s);result.putBoolean("passed",false);}finally{try{probe("clear");if(screen!=null)main(screen::finish);if(home!=null)main(home::finish);if(Build.VERSION.SDK_INT>=33&&!oldPost)shell("pm revoke ru.truetv.probe android.permission.POST_NOTIFICATIONS");if(beforeSettings!=null){SharedPreferences.Editor edit=new SettingsStore(c).data.edit().clear();for(Map.Entry<String,?> x:beforeSettings.entrySet()){Object v=x.getValue();if(v instanceof String)edit.putString(x.getKey(),(String)v);else if(v instanceof Boolean)edit.putBoolean(x.getKey(),(Boolean)v);else if(v instanceof Integer)edit.putInt(x.getKey(),(Integer)v);else if(v instanceof Long)edit.putLong(x.getKey(),(Long)v);}edit.commit();}if(beforeAccess!=null)shell(beforeAccess.equals("null")?"settings delete secure enabled_notification_listeners":"settings put secure enabled_notification_listeners "+beforeAccess);}catch(Exception e){log.append("RESTORE ").append(e);}}result.putString("report",log+"Checks="+checks);finish(result.getBoolean("passed")?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
